const tabId = 480038537;
const advisoryDetails = await browserjs(tabId, () => {
  const sections = {};

  // Risk level
  const riskH2 = document.querySelector("#risk, #risk-level, h2#risk");
  const riskSection = document.querySelector(".risk-level, [id*='risk']");

  // Let's get the text of headings and sections
  const headings = Array.from(document.querySelectorAll("h2, h3"));
  for (const h of headings) {
    const title = h.textContent.trim();
    let sibling = h.nextElementSibling;
    let content = "";
    while (sibling && !['H2', 'H3'].includes(sibling.tagName)) {
      content += sibling.textContent.trim() + "\n";
      sibling = sibling.nextElementSibling;
    }
    sections[title] = content.slice(0, 1500);
  }
  return sections;
});

