    const headings = Array.from(document.querySelectorAll("h2, h3, h4"));
    const h = headings.find(el => el.textContent.trim().toLowerCase().includes(headerText.toLowerCase()));
    if (!h) return null;
    let node = h.nextElementSibling;
    let text = "";
    while (node && !['H2', 'H3'].includes(node.tagName)) {
      text += node.innerText + "\n";
      node = node.nextElementSibling;
    }
    return text.trim();
  };

  return {
    risk: findTextUnder("Risk level"),
    safety: findTextUnder("Safety and security"),
    entry: findTextUnder("Entry and exit requirements"),
    passport: findTextUnder("Passport"),
    visas: findTextUnder("Visas"),
    health: findTextUnder("Health"),
    medications: findTextUnder("Medications"),
    crime: findTextUnder("Crime")
  };
});

console.log("Risk level:\n", res.risk?.slice(0, 500));
