const tabId = 480038539;
await tool.navigate({ tabId, url: "https://rates.ca/insurance-quotes/travel" });
await tool.wait_for({ tabId, condition: "load_state", value: "load" });
const pageData = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll("h2, h3"));
  const info = {};
  for (const h of headings) {
    const title = h.textContent.trim();
    let text = "";
    let sibling = h.nextElementSibling;
    while (sibling && !['H2', 'H3'].includes(sibling.tagName)) {
      text += sibling.innerText + "\n";
      sibling = sibling.nextElementSibling;
    }
    if (text.length > 0) {
      info[title] = text.slice(0, 1000);
    }
  }
  return info;
});
console.log("Rates.ca travel guide sections:", Object.keys(pageData));
for (const [k, v] of Object.entries(pageData)) {
  if (k.toLowerCase().includes("who") || k.toLowerCase().includes("why") || k.toLowerCase().includes("types") || k.toLowerCase().includes("cost") || k.toLowerCase().includes("provider")) {
    console.log(`=== ${k} ===\n${v.slice(0, 500)}\n`);
  }
}

